mapper.select:
SELECT 


    a.supplier_id = #{supplierId}
    AND a.status = #{status}

        AND (a.asn_no LIKE CONCAT('%', #{keyword}, '%') OR o.order_no LIKE CONCAT('%', #{keyword}, '%')
             OR s.name LIKE CONCAT('%', #{keyword}, '%') OR a.tracking_no LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY a.id DESC

SELECT oi.id AS order_item_id,
       oi.qty - oi.done_qty + oi.replenish_qty - COALESCE((
           SELECT SUM(ai.qty) FROM scm_asn_item ai JOIN scm_asn a ON a.id = ai.asn_id
           WHERE ai.order_item_id = oi.id AND a.status = 'SUBMITTED'
           AND a.id <> #{excludeAsnId}
       ), 0) AS open_qty
FROM scm_order_item oi
WHERE oi.order_id = #{orderId}
ORDER BY oi.id
